/**
 * Resolves the page an alert or search hit links to. Each href is built by `@/lib/url` from the rows it names, so it always points at a route the app serves.
 *
 * Every resolver returns `null` when the row it needs no longer exists, so a caller can skip the link rather than write a dead one.
 */
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { issuePath, projectPath, settingsPath } from "@/lib/url";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

/** The issue's page inside its workspace and project. */
export async function issueHref(
  orgId: OrgId,
  issueId: IssueId,
): Promise<string | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return null;

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  const org = await orgRepo.findOrgById(orgId);
  if (!project || !org) return null;

  return issuePath(org.slug, project.slug, issue.number);
}

/** A comment has no page of its own; it links to the issue it belongs to. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string | null> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (!comment) return null;
  return issueHref(orgId, comment.issueId);
}

/** The project's page inside its workspace. */
export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string | null> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  const org = await orgRepo.findOrgById(orgId);
  if (!project || !org) return null;

  return projectPath(org.slug, project.slug);
}

/** A settings section of the workspace, e.g. `members` or `billing`. */
export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return null;

  return settingsPath(org.slug, section);
}

