  // same `issue.assigned` event a later reassignment would publish.
  if (issue.assigneeId !== null) {
    await emit("issue.assigned", {
      ...actorEnvelope(actor),
      issueId: issue.id,
      projectId: issue.projectId,
      previousAssigneeId: null,
      assigneeId: issue.assigneeId,
    });
  }

