import { emit } from "@/lib/event-bus";
import { createProjectSchema } from "@/schemas/project";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import { rateLimitState } from "./_support/doubles/misc";
import type { Tenant } from "./_support/fixtures";
import type { CommentId, MemberId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let free: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("vfy", "growth");
  free = await createTenant("vfyfree", "free");
});

afterAll(() => {
  detach();
  cleanup();
});

const all = (actor: Tenant["actors"]["owner"], recipientId: UserId, extra = {}) =>
  notificationService.listNotifications(actor, {
    orgId: actor.orgId,
    recipientId,
    unreadOnly: false,
    limit: 100,
    cursor: null,
    ...extra,
  });

describe("verification", () => {
  it("refuses another member's inbox, settings and mark-read", async () => {
    await expect(all(tenant.actors.owner, tenant.userIds.admin)).rejects.toThrow();
    await expect(
      notificationService.updatePreference(tenant.actors.viewer, {
        orgId: tenant.org.id,
        userId: tenant.userIds.owner,
        kind: "comment_created",
        inApp: false,
        email: false,
        digestOnly: false,
      }),
    ).rejects.toThrow();
  });

  it("member.joined alerts the owner and not the joiner", async () => {
    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.viewer,
      occurredAt: new Date().toISOString() as never,
      memberId: "mem-x" as MemberId,
      userId: tenant.userIds.viewer,
      role: "viewer",
    });
    const owner = await all(tenant.actors.owner, tenant.userIds.owner, { kind: ["member_joined"] });
    const joiner = await all(tenant.actors.viewer, tenant.userIds.viewer, { kind: ["member_joined"] });
    expect(owner.items).toHaveLength(1);
    expect(owner.items[0]?.href).toBe(`/${tenant.org.slug}/settings/members`);
    expect(joiner.items).toHaveLength(0);
  });

  it("assignment at creation alerts the assignee, not a self-assigner", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Assigned at birth",
        assigneeId: tenant.userIds.admin,
      }),
    );
    const adminRows = await all(tenant.actors.admin, tenant.userIds.admin, { kind: ["issue_assigned"] });
    expect(adminRows.items.map((r) => r.href)).toContain(
      `/${tenant.org.slug}/projects/platform/issues/${issue.number}`,
    );

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Self assigned",
        assigneeId: tenant.userIds.member,
      }),
