  it("plan refusals alert the owner once per open resource", async () => {
    const actor = free.actors.member;
    // free plan: 2 projects; fixture already holds 1.
    await projectService.createProject(
      actor,
      createProjectSchema.parse({ orgId: free.org.id, name: "Alpha project", slug: "alpha-p", key: "ALP" }),
    );
    const refuse = () =>
      projectService.createProject(
        actor,
        createProjectSchema.parse({ orgId: free.org.id, name: "Beta project", slug: "beta-p", key: "BET" }),
      );
    await expect(refuse()).rejects.toThrow();
    await expect(refuse()).rejects.toThrow();

    const first = await all(free.actors.owner, free.userIds.owner, { kind: ["plan_limit_reached"] });
    expect(first.items).toHaveLength(1);
    expect(first.items[0]?.href).toBe(`/${free.org.slug}/settings/billing`);

    await notificationService.markRead(free.actors.owner, {
      orgId: free.org.id,
      notificationId: first.items[0]!.id,
    });
    await expect(refuse()).rejects.toThrow();
    const second = await all(free.actors.owner, free.userIds.owner, { kind: ["plan_limit_reached"] });
    expect(second.items).toHaveLength(2);

    // Recount never refuses, so it adds nothing.
    const { recomputeUsage } = await import("@/server/services/usage-service");
    await recomputeUsage(free.org.id);
    const third = await all(free.actors.owner, free.userIds.owner, { kind: ["plan_limit_reached"] });
    expect(third.items).toHaveLength(2);
  });

  it("inbox excludes rows switched off for in-app and paginates without loss", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "comment_created",
      inApp: false,
      email: true,
      digestOnly: false,
    });
    await notificationService.notify(tenant.org.id, "comment_created", [tenant.userIds.viewer], {
      title: "hidden", body: "x", href: "/x", actorId: null,
    });
    const viewerPage = await all(tenant.actors.viewer, tenant.userIds.viewer, { kind: ["comment_created"] });
    expect(viewerPage.items.find((r) => r.title === "hidden")).toBeUndefined();

    for (let i = 0; i < 5; i += 1) {
      await notificationService.notify(tenant.org.id, "comment_mention", [tenant.userIds.viewer], {
        title: `page ${i}`, body: "x", href: "/x", actorId: null,
      });
    }
    const seen: string[] = [];
    let cursor: string | null = null;
    do {
      const page: Awaited<ReturnType<typeof all>> = await notificationService.listNotifications(tenant.actors.viewer, {
        orgId: tenant.org.id, recipientId: tenant.userIds.viewer, unreadOnly: false, limit: 2, cursor,
      });
      seen.push(...page.items.map((r) => r.id));
      cursor = page.nextCursor;
    } while (cursor !== null);
    expect(new Set(seen).size).toBe(seen.length);
    expect(seen).toHaveLength(5);

    const marked = await notificationService.markAllRead(tenant.actors.viewer, tenant.org.id);
    expect(marked).toBe(5);
    const ownerUnread = await all(tenant.actors.owner, tenant.userIds.owner, { unreadOnly: true });
    expect(ownerUnread.items.length).toBeGreaterThan(0);
  });
